 async function applyVerifiedSync(candidateIds:string[]){if(!pendingSync)return;const approved=new Set(candidateIds),byUser=new Map<string,SyncCandidate[]>();for(const candidate of pendingSync.candidates)if(approved.has(candidate.id)){const list=byUser.get(candidate.userId);if(list)list.push(candidate);else byUser.set(candidate.userId,[candidate])}for(const[userId,matches]of byUser){const organizations=new Set(matches.map(match=>match.organization).filter((value):value is string=>!!value));if(organizations.size>1){const user=pendingSync.users.find(item=>item.id===userId);alert(`Conflicting organization tags were selected for ${user?.last}, ${user?.first}. Deselect the incorrect filename before applying.`);return}}const nextUsers=pendingSync.users.map(user=>{const matches=byUser.get(user.id);if(!matches)return user;const replacements=new Map(matches.map(match=>[match.kind,{kind:match.kind,filename:match.filename}])),organization=matches.find(match=>match.organization)?.organization??user.organization;return{...user,organization,artifacts:[...user.artifacts.filter(a=>!replacements.has(a.kind)),...replacements.values()]}});setSystems(pendingSync.systems);setUsers(nextUsers);setSelected(pendingSync.systemId);await writeSystemManifest(pendingSync.handle,pendingSync.systemId,pendingSync.systems,nextUsers);warnAuditFailure(await appendAudit(`SYNC SYSTEM: manually approved ${approved.size} artifact updates and organization assignments; ${pendingSync.unmatched.length} unmatched evidence files; scanned ${pendingSync.scanned} files`,pendingSync.systemId));setPendingSync(null);setModal(null);setSyncText(`Applied ${approved.size} updates`);setTimeout(()=>setSyncText('Sync'),2200)}
 function resetFilters(){setOrgFilter('All organizations');setRoleFilter('All roles');setPrivTypeFilter('All privileged user types');setStatusFilter('All statuses');setArtifactFilter('All artifacts');setQuery('')}
